    float sum = 0.0f;
    float sum_sq = 0.0f;

    int base_offset = batch_idx * num_features * spatial_size + feature_idx * spatial_size;

    for (int i = 0; i < spatial_size; i++) {
        float val = __half2float(input[base_offset + i]);
        sum += val;
        sum_sq += val * val;
