    // Store partial sums in shared memory
    shared_data[threadIdx.x] = sum;
    __syncthreads();

    // Reduction to compute total sum
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            shared_data[threadIdx.x] += shared_data[threadIdx.x + s];
        }
        __syncthreads();
