        if (threadIdx.x < s) {
            shared_data[threadIdx.x] += shared_data[threadIdx.x + s];
        }
        __syncthreads();
    }

    float group_var = shared_data[0] / spatial_size;
    float group_rstd = rsqrtf(group_var + 1e-5f);

    // Normalize and apply affine transformation
    int weight_bias_offset = feature_idx;
    half weight_val = weight[weight_bias_offset];
    half bias_val = bias[weight_bias_offset];

    for (int i = 0; i < spatial_size; i++) {
